test('preservation contract: user files survive upgrades INSIDE managed dirs (bytes read back)', () => {
  const tmp = scratch('preserve');
  const src = makeSource(join(tmp, 'src'));
  const dest = join(tmp, 'dest', '.claude', 'skills', 'flow');

  install({ sourceDir: src, destDir: dest });
  // User custom at root and INSIDE a previously-managed subdir; the owned guide.md gets a
  // new upstream version to prove the update really ran.
  writeFileSync(join(dest, 'notes.md'), 'my custom notes\n');
  mkdirSync(join(dest, 'references'), { recursive: true });
  writeFileSync(join(dest, 'references', 'user-added.md'), 'user note inside managed dir\n');
  mutateSource(src, 'references/guide.md', '# guide v2\n');

  const r = install({ sourceDir: src, destDir: dest });
  assert.equal(r.success, true, r.error);
  assert.equal(readFileSync(join(dest, 'notes.md'), 'utf8'), 'my custom notes\n');
  assert.equal(
    readFileSync(join(dest, 'references', 'user-added.md'), 'utf8'),
    'user note inside managed dir\n'
  );
  assert.equal(readFileSync(join(dest, 'references', 'guide.md'), 'utf8'), '# guide v2\n');
  // Customs must NOT be in the new ownership receipt (future upgrades must not prune them).
  const receipt = JSON.parse(readFileSync(join(dest, RECEIPT_NAME), 'utf8'));
  assert.equal(Object.hasOwn(receipt.files, 'notes.md'), false);
  assert.equal(Object.hasOwn(receipt.files, 'references/user-added.md'), false);
  assert.equal(Object.hasOwn(receipt.files, 'references/guide.md'), true);
  assert.deepEqual(r.preserved.sort(), ['notes.md', 'references/user-added.md']);
});

test('user-modified owned file → conflict refused BEFORE touching the original', () => {
  const tmp = scratch('conflict');
  const src = makeSource(join(tmp, 'src'));
  const dest = join(tmp, 'dest', '.claude', 'skills', 'flow');
  install({ sourceDir: src, destDir: dest });

  // User edits an OWNED file, upstream also changed it.
  writeFileSync(join(dest, 'references', 'guide.md'), '# user local edit\n');
  mutateSource(src, 'references/guide.md', '# guide v2\n');

  const before = readFileSync(join(dest, 'references', 'guide.md'), 'utf8');
  const r = install({ sourceDir: src, destDir: dest });
  assert.equal(r.success, false);
  assert.match(r.error, /user-modified owned file/);
  assert.equal(
    readFileSync(join(dest, 'references', 'guide.md'), 'utf8'),
    before,
    'original dest must be untouched on conflict'
  );
});

test('legacy dest (no receipt): differing collision refuses, custom preserved, identical idempotent', () => {
  const tmp = scratch('legacy');
  const src = makeSource(join(tmp, 'src'));
  const dest = join(tmp, 'dest', '.claude', 'skills', 'flow');
  // Hand-made legacy tree: no receipt, SKILL.md differs from source, custom file present.
  mkdirSync(join(dest, 'references'), { recursive: true });
  writeFileSync(join(dest, 'SKILL.md'), '---\nname: something-else\n---\n');
  writeFileSync(join(dest, 'references', 'guide.md'), '# guide\n'); // identical bytes
  writeFileSync(join(dest, 'keepme.txt'), 'legacy custom\n');

  const r = install({ sourceDir: src, destDir: dest });
  assert.equal(r.success, false);
  assert.match(r.error, /collision with differing bytes/);
  assert.equal(existsSync(join(dest, 'keepme.txt')), true, 'refused before touching dest');

  // Fix the collision to identical bytes → succeeds, legacy custom preserved.
  writeFileSync(join(dest, 'SKILL.md'), '---\nname: flow\n---\n');
  const r2 = install({ sourceDir: src, destDir: dest });
  assert.equal(r2.success, true, r2.error);
  assert.equal(readFileSync(join(dest, 'keepme.txt'), 'utf8'), 'legacy custom\n');
  assert.deepEqual(r2.preserved, ['keepme.txt']);
});

