test('symlink inside existing destination → refused, original preserved', () => {
  const tmp = scratch('destsymlink');
  const src = makeSource(join(tmp, 'src'));
  const dest = join(tmp, 'dest', '.claude', 'skills', 'flow');
  install({ sourceDir: src, destDir: dest });
  const external = join(tmp, 'outside.txt');
  writeFileSync(external, 'precious\n');
  try {
    symlinkSync(external, join(dest, 'references', 'user-link'));
  } catch (err) {
    if (err.code === 'EPERM' || err.code === 'ENOSYS') return; // platform cannot test
    throw err;
  }
  const r = install({ sourceDir: src, destDir: dest });
  assert.equal(r.success, false);
  assert.match(r.error, /destination symlink refused/);
  assert.equal(existsSync(join(dest, 'references', 'user-link')), true, 'user symlink intact');
});

