test('injected rename failure at promote → rollback restores the original exactly', () => {
  const tmp = scratch('promote-fail');
  const src = makeSource(join(tmp, 'src'));
  const dest = join(tmp, 'dest', '.claude', 'skills', 'flow');
  install({ sourceDir: src, destDir: dest });
  writeFileSync(join(dest, 'user.txt'), 'mine\n');
  mutateSource(src, 'references/guide.md', '# guide v2\n');

  const calls = { n: 0 };
  const r = install({
    sourceDir: src,
    destDir: dest,
    io: {
      rename: (a, b) => {
        calls.n++;
        if (calls.n === 2) throw new Error('injected promote failure'); // backup done, promote fails
        return renameSync(a, b);
      },
    },
  });
  assert.equal(r.success, false);
  assert.match(r.error, /original destination restored exactly/);
  assert.equal(existsSync(join(dest, 'user.txt')), true);
  assert.equal(readFileSync(join(dest, 'references', 'guide.md'), 'utf8'), '# guide\n');
  // No residue: no stage/backup/failed slots left in the parent.
  const parent = join(tmp, 'dest', '.claude', 'skills');
  assert.equal(readdirSync(parent).filter((n) => n.startsWith('.flow-skill')).length, 0);
});

test('injected receipt corruption at promote → verify catches it, original restored exactly', () => {
  const tmp = scratch('verify-fail');
  const src = makeSource(join(tmp, 'src'));
  const dest = join(tmp, 'dest', '.claude', 'skills', 'flow');
  install({ sourceDir: src, destDir: dest });
  writeFileSync(join(dest, 'user.txt'), 'mine\n');
  mutateSource(src, 'references/guide.md', '# guide v2\n');

  const calls = { n: 0 };
  const r = install({
    sourceDir: src,
    destDir: dest,
    io: {
      rename: (a, b) => {
        const out = renameSync(a, b);
        // Corrupt the promoted candidate AFTER the promote rename (2nd call) so the
        // post-promote verification must catch the substitution.
        if (++calls.n === 2) {
          writeFileSync(join(b, RECEIPT_NAME), '{"schema_version":1,"files":{}}\n');
        }
        return out;
      },
    },
  });
  assert.equal(r.success, false);
  assert.match(r.error, /original destination restored exactly/);
  assert.equal(readFileSync(join(dest, 'references', 'guide.md'), 'utf8'), '# guide\n');
  assert.equal(existsSync(join(dest, 'user.txt')), true);
});

test('injected rollback failure → backup kept, recoveryPath reported and readable', () => {
  const tmp = scratch('restore-fail');
  const src = makeSource(join(tmp, 'src'));
  const dest = join(tmp, 'dest', '.claude', 'skills', 'flow');
  install({ sourceDir: src, destDir: dest });
  mutateSource(src, 'references/guide.md', '# guide v2\n');

  const calls = { n: 0 };
  const r = install({
    sourceDir: src,
    destDir: dest,
    io: {
      rename: (a, b) => {
        calls.n++;
        if (calls.n === 2) {
          // Promote succeeds, but the candidate is corrupted so post-promote verification
          // fails and recovery (rename #3) runs — which is injected to fail.
          const out = renameSync(a, b);
          writeFileSync(join(b, RECEIPT_NAME), '{"schema_version":1,"files":{}}\n');
          return out;
        }
        // The restore rename is identified by its SOURCE: the backup slot. Quarantine
        // renames (source = destDir) must pass, or the restore would never be reached.
        if (String(a).includes('.flow-skill-backup-')) {
          throw new Error('injected rollback failure');
        }
        return renameSync(a, b);
      },
    },
  });
  assert.equal(r.success, false);
  assert.equal(r.code, 'EROLLBACK');
  assert.ok(r.recoveryPath, 'recoveryPath must be reported');
  assert.equal(
    readFileSync(join(r.recoveryPath, 'references', 'guide.md'), 'utf8'),
    '# guide\n',
    'backup bytes accessible at recoveryPath'
  );
  assert.match(r.error, /ORIGINAL DESTINATION PRESERVED AT/);
});

test('injected quarantine rename failure → candidate stays at dest, backup kept, both paths reported', () => {
  const tmp = scratch('quarantine-fail');
  const src = makeSource(join(tmp, 'src'));
  const dest = join(tmp, 'dest', '.claude', 'skills', 'flow');
  install({ sourceDir: src, destDir: dest });
  mutateSource(src, 'references/guide.md', '# guide v2\n');

  const calls = { n: 0 };
  const r = install({
    sourceDir: src,
    destDir: dest,
    io: {
      rename: (a, b) => {
        calls.n++;
        if (calls.n === 2) {
          // Promote succeeds; corrupt the candidate so verification fails and recovery runs.
          const out = renameSync(a, b);
          writeFileSync(join(b, RECEIPT_NAME), '{"schema_version":1,"files":{}}\n');
          return out;
        }
        if (String(b).includes('.flow-skill-failed-')) {
          throw new Error('injected quarantine failure');
        }
        return renameSync(a, b);
      },
    },
  });
  assert.equal(r.success, false);
  assert.equal(r.code, 'EROLLBACK');
  assert.ok(r.recoveryPath, 'recoveryPath (backup) must be reported');
  assert.equal(r.failedCandidatePath, dest, 'candidate stayed at dest; reported accurately');
  assert.match(r.partialState, /failed candidate still at the destination path/);
  // Backup bytes intact; bad candidate untouched at dest; no restore onto occupied dest.
  assert.equal(
    readFileSync(join(r.recoveryPath, 'references', 'guide.md'), 'utf8'),
    '# guide\n'
  );
  assert.equal(readFileSync(join(dest, RECEIPT_NAME), 'utf8'), '{"schema_version":1,"files":{}}\n');
});

